cambio_estado.py:
"""
Ecuación de cambio de estado y vano regulador.

Ecuación (tensiones horizontales H en kgf, vano a en m):

    H2² · [ H2 − H1 + α·E·S·(θ2 − θ1) + w1²·a²·E·S / (24·H1²) ] = w2²·a²·E·S / 24

Reemplaza la hoja "Tensionados" del Excel original, que tenía valores pegados
(sin fórmulas) y una carga de viento ~44 veces menor que la exigida por EH-RAA-004.
"""
from __future__ import annotations

import math
from dataclasses import dataclass

import numpy as np
from .raices import brentq

from .config import Conductor, Hipotesis


class ErrorCalculo(Exception):
    """Error de cálculo con mensaje legible para el usuario."""


# ---------------------------------------------------------------------------
def vano_regulador(vanos: list[float] | np.ndarray) -> float:
    """Vano regulador (ideal de regulación): ar = √(Σa³ / Σa)."""
    a = np.asarray(vanos, dtype=float)
    if a.size == 0 or np.any(a <= 0):
        raise ErrorCalculo("Los vanos de la sección de tendido deben ser positivos.")
    return float(math.sqrt(np.sum(a ** 3) / np.sum(a)))


def resolver_cambio_estado(H1: float, w1: float, t1: float,
                           w2: float, t2: float, a: float,
                           conductor: Conductor) -> float:
    """Devuelve la tensión horizontal H2 (kgf) en el estado 2.

    La cúbica H³ + A·H² − B = 0 tiene exactamente una raíz positiva
    (regla de Descartes), que se acota y se resuelve con Brent.
    """
    ES = conductor.ES
    A = conductor.coef_dilatacion * ES * (t2 - t1) + (w1 * a) ** 2 * ES / (24 * H1 ** 2) - H1
    B = (w2 * a) ** 2 * ES / 24.0

    def f(H):
        return H ** 3 + A * H ** 2 - B

    lo = 1e-6
    hi = max(1.0, abs(A)) + B ** (1 / 3) + 1.0
    while f(hi) < 0:
        hi *= 2
    return brentq(f, lo, hi, xtol=1e-9, maxiter=200)


def flecha_parabolica(w: float, a: float, H: float) -> float:
    return w * a * a / (8.0 * H)


def flecha_catenaria(w: float, a: float, H: float) -> float:
    C = H / w
    return C * (math.cosh(a / (2 * C)) - 1.0)


# ---------------------------------------------------------------------------
@dataclass
class EstadoTendido:
    """Resultado del cambio de estado para un vano regulador."""
    vano_regulador: float
    hipotesis_gobernante: str
    tensiones: dict[str, float]      # H (kgf) por hipótesis
    pesos: dict[str, float]          # w aparente (kgf/m) por hipótesis

    def parametro(self, clave: str) -> float:
        """Parámetro de la catenaria C = H/w (m)."""
        return self.tensiones[clave] / self.pesos[clave]


def calcular_estado(ar: float, conductor: Conductor,
                    hipotesis: dict[str, Hipotesis],
                    fluencia_delta_t: float = 0.0,
                    clave_fluencia: str = "FMAX") -> EstadoTendido:
    """Encuentra la hipótesis gobernante y las tensiones de todas las hipótesis.

    Método clásico: se supone cada hipótesis con límite a su tensión máxima
    admisible, se trasladan las demás por cambio de estado y se elige la que
    no viola ningún otro límite.
    """
    if ar <= 0:
        raise ErrorCalculo("El vano regulador debe ser positivo.")
    rot = conductor.carga_rotura_kgf
    pesos = {k: h.peso_aparente(conductor) for k, h in hipotesis.items()}
    temps = {k: h.temperatura_c + (fluencia_delta_t if k == clave_fluencia else 0.0)
             for k, h in hipotesis.items()}
    limitadas = {k: h.limite_fraccion_rotura * rot
                 for k, h in hipotesis.items() if h.limite_fraccion_rotura}
    if not limitadas:
        raise ErrorCalculo("Ninguna hipótesis tiene límite de tensión definido.")

    mejor = None
    for kref, Href in limitadas.items():
        T = {kref: Href}
        for k in hipotesis:
            if k != kref:
                T[k] = resolver_cambio_estado(Href, pesos[kref], temps[kref],
                                              pesos[k], temps[k], ar, conductor)
        viola = any(T[k] > lim * (1 + 1e-6) for k, lim in limitadas.items())
        if not viola:
            mejor = (kref, T)
            break
    if mejor is None:  # numéricamente no debería ocurrir
        raise ErrorCalculo(f"No se encontró hipótesis gobernante para ar={ar:.1f} m.")
    return EstadoTendido(ar, mejor[0], mejor[1], pesos)


def tabla_tendido(conductor: Conductor, hipotesis: dict[str, Hipotesis],
                  vanos: list[float], fluencia_delta_t: float = 0.0):
    """Tabla de tendido (equivalente corregido de la hoja 'Tensionados')."""
    import pandas as pd
    filas = []
    for a in vanos:
        e = calcular_estado(a, conductor, hipotesis, fluencia_delta_t)
        fila = {"Vano (m)": a, "Gobierna": e.hipotesis_gobernante}
        for k in hipotesis:
            H, w = e.tensiones[k], e.pesos[k]
            fila[f"{k} H (kgf)"] = round(H, 2)
            fila[f"{k} %Rot"] = round(100 * H / conductor.carga_rotura_kgf, 2)
            fila[f"{k} Flecha (m)"] = round(flecha_catenaria(w, a, H), 3)
        filas.append(fila)
    return pd.DataFrame(filas)

carga_estructuras.py:
"""
Carga masiva de estructuras desde Excel (o CSV): columnas Name, Latitud, Longitud.

- Orden por defecto: 1.ª Name, 2.ª Latitud, 3.ª Longitud. Si la fila de encabezados nombra las
  columnas (Latitud/Lat, Longitud/Lon/Long), se respeta lo que diga el encabezado.
- Name vacío → se asigna un nombre automático (AP-001, AP-002, …) sin repetir los existentes.
- Validaciones por fila: latitud y longitud numéricas (decimal con punto o coma, o GMS),
  dentro de rango (−90…90 / −180…180) y dentro de Colombia (aviso si quedan por fuera);
  columnas invertidas (latitud ≈ −75, longitud ≈ 3) se detectan y se corrigen con aviso;
  nombres repetidos y coordenadas duplicadas se informan.
"""
from __future__ import annotations

import csv
import io
import math
import re
import unicodedata

from . import geo

# Rango de Colombia continental e insular (con margen) para el aviso «fuera de Colombia»
COLOMBIA = {"lat": (-4.6, 13.6), "lon": (-82.0, -66.6)}


def _norm(t) -> str:
    s = unicodedata.normalize("NFKD", str(t)).encode("ascii", "ignore").decode().lower()
    return re.sub(r"[^a-z0-9]+", " ", s).strip()


def _texto(v) -> str:
    if v is None:
        return ""
    if isinstance(v, float):
        if math.isnan(v):
            return ""
        return repr(v)
    return str(v).strip()


def _leer_filas(contenido: bytes, nombre: str) -> list[list[str]]:
    ext = nombre.lower().rsplit(".", 1)[-1] if "." in nombre else ""
    if ext in ("xlsx", "xlsm", "xls"):
        import pandas as pd
        xls = pd.ExcelFile(io.BytesIO(contenido))
        df = pd.read_excel(xls, sheet_name=xls.sheet_names[0], header=None, dtype=object)
        return [[_texto(v) for v in fila] for fila in df.itertuples(index=False)]
    if ext in ("csv", "txt"):
        for enc in ("utf-8-sig", "cp1252", "latin-1"):
            try:
                texto = contenido.decode(enc)
                break
            except UnicodeDecodeError:
                continue
        try:
            sep = csv.Sniffer().sniff(texto[:4000], delimiters=",;\t|").delimiter
        except csv.Error:
            sep = ";" if texto.count(";") > texto.count(",") else ","
        return [[c.strip() for c in f] for f in csv.reader(io.StringIO(texto), delimiter=sep)]
    raise ValueError(f"Formato no soportado (.{ext}). Use un archivo Excel (.xlsx) o CSV.")


def _numero(txt: str, eje: str):
    """Ángulo en decimal (punto o coma) o GMS. Devuelve float o lanza ValueError."""
    t = str(txt).strip()
    if not t:
        raise ValueError("vacía")
    try:
        return float(t.replace(",", "."))
    except ValueError:
        pass
    try:
        return float(geo.leer_angulo(t, eje))
    except Exception as e:  # noqa: BLE001
        raise ValueError(f"«{t}» no es un número válido") from e


def _es_num(t: str) -> bool:
    try:
        _numero(t, "lat")
        return True
    except ValueError:
        return False


def leer_estructuras(contenido: bytes, nombre: str, existentes: list[str] | None = None) -> dict:
    filas = [f for f in _leer_filas(contenido, nombre) if any(str(c).strip() for c in f)]
    if not filas:
        raise ValueError("El archivo está vacío.")
    ancho = max(len(f) for f in filas)
    if ancho < 3:
        raise ValueError("El archivo debe tener tres columnas: Name, Latitud y Longitud "
                         f"(se encontraron {ancho}).")
    filas = [list(f) + [""] * (ancho - len(f)) for f in filas]

    # encabezado: primera fila cuyas columnas 2 y 3 no son números
    col = {"nombre": 0, "lat": 1, "lon": 2}
    encabezado = None
    if not (_es_num(filas[0][1]) or _es_num(filas[0][2])):
        encabezado = [str(c).strip() for c in filas[0]]
        n = [_norm(c) for c in encabezado]
        for j, h in enumerate(n):
            if h in ("lat", "latitud", "latitude", "y lat") or h.startswith("latitud"):
                col["lat"] = j
            elif h in ("lon", "long", "lng", "longitud", "longitude") or h.startswith("longitud"):
                col["lon"] = j
            elif h in ("name", "nombre", "estructura", "poste", "apoyo", "id"):
                col["nombre"] = j
        filas = filas[1:]
        if col["lat"] == col["lon"]:
            raise ValueError("El encabezado no permite distinguir Latitud de Longitud.")
    if not filas:
        raise ValueError("El archivo solo tiene encabezados, sin estructuras.")

    usados = set(str(x) for x in (existentes or []))
    def auto_nombre():
        k = 1
        while f"AP-{k:03d}" in usados:
            k += 1
        n = f"AP-{k:03d}"
        usados.add(n)
        return n

    out, vistos, coords = [], {}, {}
    fila0 = 2 if encabezado else 1
    for k, f in enumerate(filas):
        r = {"fila": fila0 + k, "nombre": str(f[col["nombre"]]).strip(), "lat": None, "lon": None,
             "errores": [], "avisos": [], "nombre_auto": False}
        try:
            r["lat"] = _numero(f[col["lat"]], "lat")
        except ValueError as e:
            r["errores"].append(f"Latitud {e}")
        try:
            r["lon"] = _numero(f[col["lon"]], "lon")
        except ValueError as e:
            r["errores"].append(f"Longitud {e}")
        la, lo = r["lat"], r["lon"]
        if la is not None and lo is not None:
            # columnas invertidas: «latitud» con valor de longitud de Colombia y viceversa
            if (COLOMBIA["lon"][0] <= la <= COLOMBIA["lon"][1] and COLOMBIA["lat"][0] <= lo <= COLOMBIA["lat"][1]):
                r["lat"], r["lon"] = lo, la
                la, lo = lo, la
                r["avisos"].append("Latitud y longitud venían invertidas: se corrigieron.")
            if not (-90 <= la <= 90):
                r["errores"].append(f"Latitud {la:g} fuera de rango (−90 a 90).")
            if not (-180 <= lo <= 180):
                r["errores"].append(f"Longitud {lo:g} fuera de rango (−180 a 180).")
            if not r["errores"] and not (COLOMBIA["lat"][0] <= la <= COLOMBIA["lat"][1]
                                         and COLOMBIA["lon"][0] <= lo <= COLOMBIA["lon"][1]):
                r["errores"].append(f"Coordenada ({la:.6f}, {lo:.6f}) fuera de Colombia. "
                                    "Verifique el signo (en Colombia la longitud es negativa).")
        if not r["nombre"]:
            r["nombre"] = auto_nombre()
            r["nombre_auto"] = True
            r["avisos"].append(f"Sin nombre: se asignó «{r['nombre']}».")
        elif r["nombre"] in usados:
            r["errores"].append(f"El nombre «{r['nombre']}» ya existe" +
                                (" en el archivo." if r["nombre"] in vistos else " en el proyecto."))
        else:
            usados.add(r["nombre"])
        vistos[r["nombre"]] = r["fila"]
        if not r["errores"]:
            clave = (round(r["lat"], 7), round(r["lon"], 7))
            if clave in coords:
                r["avisos"].append(f"Misma coordenada que la fila {coords[clave]}.")
            coords[clave] = r["fila"]
        out.append(r)

    validas = [r for r in out if not r["errores"]]
    return {
        "encabezado": encabezado,
        "columnas_usadas": {k: (encabezado[v] if encabezado else f"Columna {v + 1}") for k, v in col.items()},
        "filas": out,
        "validas": len(validas),
        "con_error": len(out) - len(validas),
        "filas_con_error": [r["fila"] for r in out if r["errores"]],
    }


def plantilla_xlsx() -> bytes:
    """Plantilla de ejemplo con las tres columnas."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill
    wb = Workbook()
    ws = wb.active
    ws.title = "Estructuras"
    ws.append(["Name", "Latitud", "Longitud"])
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="17324D")
    ws.append(["AP-001", 2.927300, -75.281900])
    ws.append(["AP-002", 2.928100, -75.281200])
    ws.append(["", 2.929000, -75.280500])
    ws.column_dimensions["A"].width = 16
    ws.column_dimensions["B"].width = 14
    ws.column_dimensions["C"].width = 14
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()

catenaria.py:
"""
Catenaria de un vano entre dos puntos de amarre (posiblemente a distinto nivel).

    y(x) = k + C·cosh((x − b)/C)        C = H / w  (parámetro, m)

Mejoras frente al notebook original:
  * Con C conocido (cambio de estado) la catenaria tiene SOLUCIÓN CERRADA:
        b = xm − C·asinh( Δy / (2·C·sinh(a / 2C)) )
    sin fsolve ni estimaciones iniciales.
  * Si se parte de una flecha, la flecha se mide como en la práctica de diseño:
    distancia vertical máxima entre la cuerda (recta entre amarres) y el
    conductor. El original usaba "apoyo más bajo − vértice", que es incorrecto en
    vanos inclinados y no tiene solución cuando el vértice cae fuera del vano.
  * Se verifica convergencia y dominio; los errores se reportan, no se ocultan.
"""
from __future__ import annotations

import math
from dataclasses import dataclass

import numpy as np
from .raices import brentq

from .cambio_estado import ErrorCalculo

_LIM_ARG = 700.0  # cosh/sinh desbordan cerca de 710


@dataclass(frozen=True)
class Catenaria:
    x1: float
    y1: float
    x2: float
    y2: float
    C: float     # parámetro (m)
    b: float     # abscisa del vértice
    k: float     # desplazamiento vertical

    # ---------------------------------------------------------------- básicos
    @property
    def vano(self) -> float:
        return self.x2 - self.x1

    @property
    def desnivel(self) -> float:
        return self.y2 - self.y1

    def y(self, x):
        return self.k + self.C * np.cosh((np.asarray(x) - self.b) / self.C)

    def cuerda(self, x):
        return self.y1 + (np.asarray(x) - self.x1) * self.desnivel / self.vano

    @property
    def vertice(self) -> tuple[float, float]:
        return self.b, self.k + self.C

    @property
    def vertice_en_vano(self) -> bool:
        return self.x1 <= self.b <= self.x2

    # --------------------------------------------------------------- derivados
    @property
    def longitud(self) -> float:
        """Longitud real de conductor en el vano (m)."""
        C, b = self.C, self.b
        return C * (math.sinh((self.x2 - b) / C) - math.sinh((self.x1 - b) / C))

    @property
    def x_flecha_maxima(self) -> float:
        """Punto donde la tangente es paralela a la cuerda."""
        m = self.desnivel / self.vano
        return float(np.clip(self.b + self.C * math.asinh(m), self.x1, self.x2))

    @property
    def flecha(self) -> float:
        """Flecha máxima medida verticalmente desde la cuerda (m)."""
        x = self.x_flecha_maxima
        return float(self.cuerda(x) - self.y(x))

    @property
    def flecha_centro(self) -> float:
        xm = 0.5 * (self.x1 + self.x2)
        return float(self.cuerda(xm) - self.y(xm))

    def tension(self, x, w: float):
        """Tensión total del conductor (kgf) en la abscisa x, para peso w (kgf/m)."""
        return w * self.C * np.cosh((np.asarray(x) - self.b) / self.C)

    def tensiones_apoyos(self, w: float) -> tuple[float, float]:
        return float(self.tension(self.x1, w)), float(self.tension(self.x2, w))

    def muestrear(self, n: int = 200) -> tuple[np.ndarray, np.ndarray]:
        x = np.linspace(self.x1, self.x2, n)
        return x, self.y(x)

    def ecuacion(self) -> str:
        signo = "+" if self.k >= 0 else "-"
        return (f"y = {self.C:.4f}·cosh((x − {self.b:.4f})/{self.C:.4f}) "
                f"{signo} {abs(self.k):.4f}")


# ---------------------------------------------------------------------------
def _validar_puntos(x1, y1, x2, y2):
    vals = (x1, y1, x2, y2)
    if not all(math.isfinite(v) for v in vals):
        raise ErrorCalculo("Coordenadas no numéricas o vacías.")
    if x2 <= x1:
        raise ErrorCalculo(f"La abscisa final ({x2}) debe ser mayor que la inicial ({x1}).")


def catenaria_por_parametro(x1: float, y1: float, x2: float, y2: float,
                            C: float) -> Catenaria:
    """Catenaria que pasa por (x1,y1) y (x2,y2) con parámetro C = H/w (solución exacta)."""
    _validar_puntos(x1, y1, x2, y2)
    if not (C > 0 and math.isfinite(C)):
        raise ErrorCalculo(f"Parámetro de catenaria inválido: C = {C}.")
    a = x2 - x1
    if a / (2 * C) > _LIM_ARG:
        raise ErrorCalculo(f"Parámetro C = {C:.3f} m demasiado pequeño para un vano de {a:.1f} m.")
    xm = 0.5 * (x1 + x2)
    b = xm - C * math.asinh((y2 - y1) / (2 * C * math.sinh(a / (2 * C))))
    k = y1 - C * math.cosh((x1 - b) / C)
    return Catenaria(x1, y1, x2, y2, C, b, k)


def catenaria_por_flecha(x1: float, y1: float, x2: float, y2: float,
                         flecha: float) -> Catenaria:
    """Catenaria cuya flecha máxima (desde la cuerda) es la indicada."""
    _validar_puntos(x1, y1, x2, y2)
    if not (flecha > 0 and math.isfinite(flecha)):
        raise ErrorCalculo(f"Flecha inválida ({flecha}) en el vano {x1:.2f}–{x2:.2f}. "
                           "Debe ser mayor que cero.")
    a = x2 - x1

    def g(C):
        return catenaria_por_parametro(x1, y1, x2, y2, C).flecha - flecha

    c_lo = a / (2 * _LIM_ARG) * 1.01
    c_hi = max(a, 1.0)
    while g(c_hi) > 0:          # flecha aún grande → aumentar C
        c_hi *= 4
        if c_hi > 1e9:
            raise ErrorCalculo("No fue posible ajustar la catenaria a la flecha dada.")
    if g(c_lo) < 0:
        raise ErrorCalculo(f"Flecha {flecha:.2f} m excesiva para un vano de {a:.1f} m.")
    C = brentq(g, c_lo, c_hi, xtol=1e-10, maxiter=300)
    return catenaria_por_parametro(x1, y1, x2, y2, C)

datos.py:
"""
Lectura y validación del archivo de datos (Excel).

Formato compatible con el DATOS.xlsx original (primera hoja):

    Apoyo | Coordenada en X | Coordenada en Y | Vano | Flecha

Columnas OPCIONALES nuevas (cualquier orden; se reconocen por nombre):
    Altura amarre (m)  -> altura del conductor sobre el terreno en el apoyo.
                          Si existe, "Coordenada en Y" se interpreta como COTA DEL TERRENO.
    Tipo               -> R/RET/T/FIN/ANCLAJE = retención (corta la sección de tendido),
                          S/SUS = suspensión. Primer y último apoyo siempre son retención.

Hojas OPCIONALES:
    Terreno      -> perfil topográfico (Abscisa, Cota) para verificar distancias reales.
    Tensionados  -> si trae la fila de "Calibre", se leen las características del conductor.

Mejoras frente al original: las columnas se ubican por NOMBRE (no por posición
fija), no se asume que las flechas empiezan en la fila 3, y se valida todo antes
de calcular, devolviendo mensajes claros en vez de excepciones crípticas.
"""
from __future__ import annotations

import math
import unicodedata
from dataclasses import dataclass, field
from pathlib import Path

import numpy as np
import pandas as pd

from .config import Conductor, Criterios


def _norm(txt) -> str:
    s = unicodedata.normalize("NFKD", str(txt)).encode("ascii", "ignore").decode()
    return " ".join(s.lower().replace("\n", " ").split())


# alias de columnas (texto normalizado contiene ...)
_ALIAS = {
    "apoyo": [("apoyo",), ("poste",), ("estructura n",), ("nombre",)],
    "x": [("coordenada en x",), ("coord x",), ("abscisa",), ("x",)],
    "y": [("coordenada en y",), ("coord y",), ("cota",), ("elevacion",), ("y",)],
    "vano": [("vano",)],
    "flecha": [("flecha",)],
    "altura": [("altura",)],
    "tipo": [("tipo",), ("funcion",)],
}


def _mapear_columnas(encabezados: list[str]) -> dict[str, int]:
    norm = [_norm(h) for h in encabezados]
    usado: set[int] = set()
    mapa: dict[str, int] = {}
    # primero coincidencias exactas, luego "contiene"
    for exacto in (True, False):
        for clave, alias in _ALIAS.items():
            if clave in mapa:
                continue
            for (patron,) in alias:
                for i, h in enumerate(norm):
                    if i in usado or not h:
                        continue
                    ok = (h == patron) if exacto else (patron in h.split() or
                                                       (len(patron) > 2 and patron in h))
                    if clave == "apoyo" and "altura" in h:
                        ok = False
                    if ok:
                        mapa[clave] = i
                        usado.add(i)
                        break
                if clave in mapa:
                    break
    return mapa


def _es_retencion(valor) -> bool:
    if valor is None or (isinstance(valor, float) and math.isnan(valor)):
        return False
    s = _norm(valor)
    return s.startswith(("r", "t", "f", "anc", "ang")) or "reten" in s or "termin" in s


@dataclass
class DatosLinea:
    archivo: str
    apoyos: pd.DataFrame                       # nombre, x, y, altura, retencion
    flechas_excel: list[float] | None = None   # una por vano (si existen)
    vanos_excel: list[float] | None = None
    conductor: Conductor | None = None
    terreno: pd.DataFrame | None = None        # columnas x, cota
    y_es_terreno: bool = False
    advertencias: list[str] = field(default_factory=list)
    errores: list[str] = field(default_factory=list)
    deflexiones: list | None = None              # ángulo en cada apoyo (si hay coordenadas)
    geo: list | None = None                      # (lat, lon) por apoyo
    estructuras: list | None = None              # poste y templetes por apoyo (dicts)

    @property
    def n_apoyos(self) -> int:
        return len(self.apoyos)

    @property
    def n_vanos(self) -> int:
        return max(0, len(self.apoyos) - 1)

    @property
    def ok(self) -> bool:
        return not self.errores


# ---------------------------------------------------------------------------
def _leer_conductor(xls: pd.ExcelFile) -> Conductor | None:
    hoja = next((h for h in xls.sheet_names if "tension" in _norm(h)), None)
    if hoja is None:
        return None
    df = pd.read_excel(xls, sheet_name=hoja, header=None, nrows=40)
    for i in range(len(df) - 1):
        if _norm(df.iat[i, 0]) == "calibre":
            v = df.iloc[i + 1, :7].tolist()
            try:
                return Conductor(nombre=str(v[0]), seccion_mm2=float(v[1]),
                                 carga_rotura_kgf=float(v[2]), peso_kgf_m=float(v[3]),
                                 modulo_elasticidad=float(v[4]), coef_dilatacion=float(v[5]),
                                 diametro_mm=float(v[6]))
            except (TypeError, ValueError):
                return None
    return None


def _leer_terreno(xls: pd.ExcelFile) -> pd.DataFrame | None:
    hoja = next((h for h in xls.sheet_names if "terreno" in _norm(h) or "perfil" in _norm(h)), None)
    if hoja is None:
        return None
    df = pd.read_excel(xls, sheet_name=hoja)
    m = _mapear_columnas(list(df.columns))
    if "x" not in m or "y" not in m:
        return None
    t = pd.DataFrame({"x": pd.to_numeric(df.iloc[:, m["x"]], errors="coerce"),
                      "cota": pd.to_numeric(df.iloc[:, m["y"]], errors="coerce")}).dropna()
    return t.sort_values("x").reset_index(drop=True) if len(t) >= 2 else None


def _leer_tablas_excel(fuente, nombre: str):
    """Lee el Excel y devuelve (filas, terreno, conductor, errores).

    `filas` es una lista de dicts {nombre, x, y, altura, tipo, vano, flecha, fila_excel}.
    """
    try:
        xls = pd.ExcelFile(fuente)
    except Exception as e:  # archivo abierto, dañado, formato errado
        return None, None, None, [f"No se pudo abrir el Excel ({e}). ¿Está abierto en Excel?"]

    hoja = next((h for h in xls.sheet_names if _norm(h) in ("datos", "hoja1", "apoyos")),
                xls.sheet_names[0])
    crudo = pd.read_excel(xls, sheet_name=hoja, header=None)
    if crudo.empty:
        return None, None, None, [f"La hoja '{hoja}' está vacía."]
    fila_enc = next((i for i in range(min(20, len(crudo)))
                     if any("apoyo" in _norm(v) for v in crudo.iloc[i].tolist())), 0)
    enc = [str(v) for v in crudo.iloc[fila_enc].tolist()]
    m = _mapear_columnas(enc)
    faltan = [c for c in ("apoyo", "x", "y") if c not in m]
    if faltan:
        return None, None, None, [f"Hoja '{hoja}': no se encontraron las columnas {faltan}. "
                                  f"Encabezados leídos: {enc}"]
    cuerpo = crudo.iloc[fila_enc + 1:].reset_index(drop=True)
    filas = []
    for i in range(len(cuerpo)):
        fila = {k: cuerpo.iat[i, j] for k, j in m.items()}
        fila = {k: (None if (isinstance(v, float) and math.isnan(v)) else v) for k, v in fila.items()}
        if fila.get("x") is None and fila.get("y") is None and fila.get("apoyo") is None:
            break
        fila["nombre"] = fila.pop("apoyo", None)
        fila["fila_excel"] = fila_enc + i + 2
        filas.append(fila)
    return filas, _leer_terreno(xls), _leer_conductor(xls), []


def leer_datos(ruta, criterios: Criterios | None = None) -> DatosLinea:
    """Lee un Excel desde una ruta, bytes o un objeto tipo archivo."""
    if isinstance(ruta, (bytes, bytearray)):
        import io
        fuente, nombre = io.BytesIO(ruta), "archivo.xlsx"
    elif hasattr(ruta, "read"):
        fuente, nombre = ruta, getattr(ruta, "name", "archivo.xlsx")
    else:
        fuente = nombre = str(ruta)
        if not Path(fuente).exists():
            return DatosLinea(nombre, pd.DataFrame(), errores=[f"No existe el archivo: {ruta}"])
    filas, terreno, conductor, err = _leer_tablas_excel(fuente, nombre)
    if err:
        return DatosLinea(nombre, pd.DataFrame(), errores=err)
    return construir_datos(filas, terreno, conductor, criterios, nombre)


def _num(v):
    if v is None:
        return None
    if isinstance(v, str):
        v = v.strip().replace(",", ".")
        if v == "":
            return None
    try:
        f = float(v)
    except (TypeError, ValueError):
        return "ERR"
    return None if math.isnan(f) else f


def construir_datos(filas: list[dict], terreno=None, conductor: Conductor | None = None,
                    criterios: Criterios | None = None, origen: str = "datos") -> DatosLinea:
    """Construye y valida los datos de la línea a partir de filas (Excel, web o JSON).

    filas: [{nombre, x, y, altura?, tipo?, vano?, flecha?, fila_excel?}, ...]
    terreno: DataFrame (x, cota) o lista de {x, cota}.
    """
    criterios = criterios or Criterios()
    adv: list[str] = []
    err: list[str] = []
    if terreno is not None and not isinstance(terreno, pd.DataFrame):
        t = pd.DataFrame(list(terreno))
        if len(t) and {"x", "cota"} <= set(t.columns):
            t = t[["x", "cota"]].apply(pd.to_numeric, errors="coerce").dropna()
            terreno = t.sort_values("x").reset_index(drop=True) if len(t) >= 2 else None
        else:
            terreno = None

    validas = []
    for k, f in enumerate(filas):
        ref = f"Fila {f.get('fila_excel', k + 1)}"
        x, y = _num(f.get("x")), _num(f.get("y"))
        nombre = f.get("nombre")
        if x is None and y is None and (nombre in (None, "")):
            continue
        if x in (None, "ERR") or y in (None, "ERR"):
            err.append(f"{ref}: apoyo '{nombre or ''}' sin coordenada X o Y válida.")
            continue
        alt = _num(f.get("altura"))
        if alt == "ERR":
            err.append(f"{ref}: altura de amarre no numérica.")
            alt = None
        validas.append({
            "nombre": str(nombre) if nombre not in (None, "") else f"AP{len(validas) + 1:03d}",
            "x": x, "y": y, "altura": np.nan if alt is None else alt,
            "retencion": _es_retencion(f.get("tipo")),
            "fila_excel": f.get("fila_excel", k + 1),
            "_vano": _num(f.get("vano")), "_flecha": _num(f.get("flecha")),
        })
    ap = pd.DataFrame(validas, columns=["nombre", "x", "y", "altura", "retencion", "fila_excel",
                                        "_vano", "_flecha"])

    # ----------------------------------------------------------- validaciones
    if len(ap) < 2:
        err.append("Se requieren al menos 2 apoyos con coordenadas.")
    if len(ap):
        ap.loc[0, "retencion"] = True
        ap.loc[len(ap) - 1, "retencion"] = True
        dup = ap["nombre"][ap["nombre"].duplicated()].tolist()
        if dup:
            adv.append(f"Nombres de apoyo repetidos: {sorted(set(dup))}.")
        dx = np.diff(ap["x"].to_numpy(dtype=float))
        for j in np.where(dx <= 0)[0]:
            err.append(f"X no creciente entre {ap.nombre[j]} (x={ap.x[j]}) y "
                       f"{ap.nombre[j + 1]} (x={ap.x[j + 1]}). Las abscisas deben ser crecientes.")
        for j, a in enumerate(dx):
            if a <= 0:
                continue
            if a < criterios.vano_min_alerta_m:
                adv.append(f"Vano {j + 1} ({ap.nombre[j]}→{ap.nombre[j + 1]}) muy corto: {a:.1f} m.")
            if a > criterios.vano_max_alerta_m:
                adv.append(f"Vano {j + 1} ({ap.nombre[j]}→{ap.nombre[j + 1]}) muy largo: {a:.1f} m.")
            dy = ap.y[j + 1] - ap.y[j]
            if abs(dy) / a > criterios.pendiente_max_alerta:
                adv.append(f"Vano {j + 1} ({ap.nombre[j]}→{ap.nombre[j + 1]}): desnivel "
                           f"{dy:+.1f} m en {a:.1f} m ({100 * abs(dy) / a:.0f} %). "
                           "Verifique la cota (posible error de digitación).")
        yy = ap["y"].to_numpy(dtype=float)
        for j in range(1, len(yy) - 1):
            d1, d2 = yy[j] - yy[j - 1], yy[j] - yy[j + 1]
            if d1 * d2 > 0 and min(abs(d1), abs(d2)) > 15:
                adv.append(f"Apoyo {ap.nombre[j]}: cota {yy[j]:g} se aparta >15 m de ambos vecinos "
                           f"({yy[j - 1]:g}, {yy[j + 1]:g}). Revise el dato.")

    # columnas de vano/flecha (modo legado)
    flechas = vanos = None
    if len(ap) > 1:
        fl = ap["_flecha"].iloc[1:].tolist()
        if any(v is not None and not pd.isna(v) for v in fl):
            if any(v is None or pd.isna(v) or v == "ERR" for v in fl):
                adv.append("La columna 'Flecha' tiene celdas vacías o con fórmulas sin calcular "
                           "(abra y guarde el Excel en Excel). El modo 'excel' no estará disponible.")
            else:
                flechas = [float(v) for v in fl]
        vn = ap["_vano"].iloc[1:].tolist()
        if any(v is not None and not pd.isna(v) for v in vn):
            vanos = [float(v) if v not in (None, "ERR") else np.nan for v in vn]
            dxx = np.diff(ap["x"].to_numpy(dtype=float))
            for j, (v, d) in enumerate(zip(vanos, dxx)):
                if not pd.isna(v) and abs(v - d) > 0.5:
                    adv.append(f"Vano {j + 1}: columna 'Vano' = {v:g} m pero ΔX = {d:.2f} m. "
                               "Se usa ΔX.")
    ap = ap.drop(columns=["_vano", "_flecha"])

    # interpretación de la cota Y
    y_es_terreno = False
    if ap["altura"].notna().any() or criterios.altura_amarre_defecto_m is not None:
        y_es_terreno = True
        if ap["altura"].isna().any():
            if criterios.altura_amarre_defecto_m is None:
                err.append("Hay apoyos sin 'Altura amarre' y no se definió una altura por defecto.")
            else:
                ap["altura"] = ap["altura"].fillna(criterios.altura_amarre_defecto_m)
    else:
        ap["altura"] = 0.0
        adv.append("No hay columna 'Altura amarre': se asume que 'Coordenada en Y' es la cota "
                   "del PUNTO DE AMARRE del conductor (como el programa original). Sin la cota "
                   "del terreno no se puede verificar la distancia mínima a tierra.")
    ap["altura"] = ap["altura"].astype(float)
    ap["x"] = ap["x"].astype(float)
    ap["y"] = ap["y"].astype(float)
    ap["retencion"] = ap["retencion"].astype(bool)

    return DatosLinea(origen, ap, flechas, vanos, conductor, terreno, y_es_terreno, adv, err)

importacion.py:
"""
Importación de postes desde Excel, CSV, KML y KMZ con mapeo de columnas,
vista previa, validación y transformación de coordenadas.

Flujo (sin efectos hasta confirmar):
  1. leer_tabla(bytes, nombre)      -> columnas + filas en texto
  2. sugerir_mapeo(columnas)         -> campo -> columna (el usuario lo ajusta)
  3. previsualizar(tabla, mapeo, sistema, georref) -> postes, errores, avisos, candidatos
  4. el cliente confirma y guarda los postes en el proyecto
"""
from __future__ import annotations

import csv
import io
import math
import re
import unicodedata
import uuid
import zipfile
from xml.etree import ElementTree as ET

import pandas as pd

from . import geo

CAMPOS = {
    "nombre": "Número / nombre del poste",
    "id": "Identificador (opcional)",
    "lat": "Latitud",
    "lon": "Longitud",
    "este": "Este / X",
    "norte": "Norte / Y",
    "z": "Cota Z (m)",
    "altura": "Altura de amarre (m)",
    "poste_altura": "Altura del poste (m)",
    "poste_rotura": "Carga de rotura del poste (kgf)",
    "poste_peso": "Peso del poste (kg)",
    "tipo": "Tipo de estructura (R/S)",
    "conductor": "Conductor asignado",
    "obs": "Observaciones",
}

_ALIAS = {
    "nombre": ["apoyo", "poste", "numero", "nro", "no.", "name", "nombre", "punto"],
    "id": ["id", "identificador", "codigo"],
    "lat": ["latitud", "lat", "latitude"],
    "lon": ["longitud", "lon", "long", "longitude", "lng"],
    "este": ["este", "east", "easting", "coordenada en x", "coord x", "x"],
    "norte": ["norte", "north", "northing", "coordenada en y", "coord y", "y"],
    "z": ["cota", "z", "elevacion", "altitud", "alt", "altitude", "h"],
    "altura": ["altura amarre", "altura de amarre", "altura"],
    "poste_altura": ["altura poste", "altura del poste", "longitud poste", "longitud del poste", "long poste", "l poste"],
    "poste_rotura": ["carga rotura", "carga de rotura", "rotura", "resistencia", "kgf"],
    "poste_peso": ["peso poste", "peso del poste", "peso"],
    "tipo": ["tipo", "estructura", "tipo estructura"],
    "conductor": ["conductor", "calibre"],
    "obs": ["observaciones", "obs", "descripcion", "description", "nota"],
}


def _norm(t) -> str:
    s = unicodedata.normalize("NFKD", str(t)).encode("ascii", "ignore").decode()
    return re.sub(r"\s+", " ", re.sub(r"[()\[\]_]", " ", s.lower())).strip()


def nuevo_id() -> str:
    return "P-" + uuid.uuid4().hex[:10]


# ------------------------------------------------------------------ lectura
def leer_tabla(contenido: bytes, nombre: str) -> dict:
    """Devuelve {"formato", "columnas", "filas" (lista de listas de texto), "linea" (KML)}."""
    ext = nombre.lower().rsplit(".", 1)[-1] if "." in nombre else ""
    if ext in ("kml", "kmz"):
        return _leer_kml(contenido, ext == "kmz")
    if ext == "csv" or ext == "txt":
        texto = _decodificar(contenido)
        try:
            dialecto = csv.Sniffer().sniff(texto[:4000], delimiters=",;\t|")
            sep = dialecto.delimiter
        except csv.Error:
            sep = ";" if texto.count(";") > texto.count(",") else ","
        filas = [f for f in csv.reader(io.StringIO(texto), delimiter=sep)]
        return _con_encabezado(filas, "csv")
    if ext in ("xlsx", "xlsm", "xls"):
        xls = pd.ExcelFile(io.BytesIO(contenido))
        hoja = next((h for h in xls.sheet_names if _norm(h) in ("datos", "postes", "apoyos", "hoja1")),
                    xls.sheet_names[0])
        df = pd.read_excel(xls, sheet_name=hoja, header=None, dtype=object)
        filas = [["" if (v is None or (isinstance(v, float) and math.isnan(v))) else _texto(v)
                  for v in fila] for fila in df.itertuples(index=False)]
        t = _con_encabezado(filas, "excel")
        t["hoja"] = hoja
        t["hojas"] = xls.sheet_names
        return t
    raise geo.ErrorGeo(f"Formato no soportado: .{ext}. Use Excel, CSV, KML o KMZ.")


def _texto(v) -> str:
    if isinstance(v, float):
        return str(int(v)) if v.is_integer() else repr(v)
    return str(v)


def _decodificar(b: bytes) -> str:
    for enc in ("utf-8-sig", "cp1252", "latin-1"):
        try:
            return b.decode(enc)
        except UnicodeDecodeError:
            continue
    return b.decode("utf-8", "replace")


def _con_encabezado(filas: list[list[str]], formato: str) -> dict:
    filas = [f for f in filas if any(str(c).strip() for c in f)]
    if not filas:
        raise geo.ErrorGeo("El archivo no tiene datos.")
    ancho = max(len(f) for f in filas)
    filas = [list(f) + [""] * (ancho - len(f)) for f in filas]
    # encabezado = primera fila con mayoría de celdas no numéricas
    def es_num(c):
        try:
            float(str(c).replace(",", "."))
            return True
        except ValueError:
            return False
    idx = 0
    for i, f in enumerate(filas[:15]):
        no_num = sum(1 for c in f if str(c).strip() and not es_num(c))
        if no_num >= max(2, len([c for c in f if str(c).strip()]) // 2):
            idx = i
            break
    enc = [str(c).strip() or f"Columna {j + 1}" for j, c in enumerate(filas[idx])]
    if all(es_num(c) or not str(c).strip() for c in filas[idx]):  # sin encabezado
        enc = [f"Columna {j + 1}" for j in range(ancho)]
        idx = -1
    return {"formato": formato, "columnas": enc, "filas": filas[idx + 1:]}


_KML_NS = {"k": "http://www.opengis.net/kml/2.2"}


def _leer_kml(contenido: bytes, kmz: bool) -> dict:
    if kmz:
        with zipfile.ZipFile(io.BytesIO(contenido)) as z:
            nombre = next((n for n in z.namelist() if n.lower().endswith(".kml")), None)
            if not nombre:
                raise geo.ErrorGeo("El KMZ no contiene un archivo .kml.")
            contenido = z.read(nombre)
    try:
        raiz = ET.fromstring(contenido)
    except ET.ParseError as e:
        raise geo.ErrorGeo(f"KML inválido: {e}") from None
    ns = raiz.tag.split("}")[0] + "}" if raiz.tag.startswith("{") else ""
    filas, linea = [], []
    for pm in raiz.iter(f"{ns}Placemark"):
        nombre = (pm.findtext(f"{ns}name") or "").strip()
        desc = (pm.findtext(f"{ns}description") or "").strip()
        extra = {d.get("name"): (d.findtext(f"{ns}value") or "") for d in pm.iter(f"{ns}Data")}
        pt = pm.find(f".//{ns}Point/{ns}coordinates")
        if pt is not None and pt.text:
            c = pt.text.strip().split(",")
            lon, lat = c[0], c[1]
            alt = c[2] if len(c) > 2 else ""
            filas.append([nombre, extra.get("id", ""), lat, lon, extra.get("cota_z", alt if alt not in ("0", "0.0") else ""),
                          extra.get("altura", ""), extra.get("tipo", ""), extra.get("conductor", ""), desc])
        ls = pm.find(f".//{ns}LineString/{ns}coordinates")
        if ls is not None and ls.text and not linea:
            for tok in ls.text.split():
                c = tok.split(",")
                if len(c) >= 2:
                    linea.append((float(c[1]), float(c[0])))
    if not filas:
        raise geo.ErrorGeo("El KML no contiene puntos (Placemark con Point).")
    return {"formato": "kml", "columnas": ["Nombre", "id", "Latitud", "Longitud", "Cota", "Altura amarre",
                                           "Tipo", "Conductor", "Descripcion"],
            "filas": filas, "linea": linea, "sistema_declarado": "WGS84"}


# ------------------------------------------------------------------ mapeo
def sugerir_mapeo(columnas: list[str]) -> dict:
    norm = [_norm(c) for c in columnas]
    mapa, usadas = {}, set()
    for exacto in (True, False):
        for campo, alias in _ALIAS.items():
            if campo in mapa:
                continue
            for al in alias:
                for i, h in enumerate(norm):
                    if i in usadas:
                        continue
                    ok = h == al if exacto else (al in h.split() or (len(al) > 3 and al in h))
                    if campo in ("nombre",) and "altura" in h:
                        ok = False
                    if campo == "altura" and ("amarre" not in h or "poste" in h) and not exacto:
                        ok = False
                    if ok:
                        mapa[campo] = columnas[i]
                        usadas.add(i)
                        break
                if campo in mapa:
                    break
    return mapa


# ------------------------------------------------------------------ vista previa
def _num(t):
    if t is None:
        return None
    s = str(t).strip().replace(" ", "")
    if s == "":
        return None
    if s.count(",") == 1 and s.count(".") == 0:
        s = s.replace(",", ".")
    elif s.count(",") >= 1 and s.count(".") == 1 and s.index(",") < s.index("."):
        s = s.replace(",", "")  # 1,234.5
    try:
        v = float(s)
    except ValueError:
        return "ERR"
    return v if math.isfinite(v) else "ERR"


def previsualizar(tabla: dict, mapeo: dict, sistema: str | None,
                  georref: dict | None = None, orden: str = "archivo") -> dict:
    """Interpreta las filas y transforma coordenadas. No guarda nada."""
    cols = tabla["columnas"]
    idx = {campo: cols.index(c) for campo, c in mapeo.items() if c in cols}
    errores, avisos = [], []
    s = geo.SISTEMAS.get(sistema) if sistema else None
    usa_geo = "lat" in idx and "lon" in idx
    usa_proy = "este" in idx and "norte" in idx
    if not (usa_geo or usa_proy):
        return {"ok": False, "errores": ["Asigne las columnas de coordenadas (Latitud y Longitud, o Este y Norte)."],
                "postes": [], "avisos": [], "candidatos": []}

    def celda(f, campo):
        return f[idx[campo]] if campo in idx and idx[campo] < len(f) else ""

    # candidatos de sistema (ayuda, nunca decisión)
    muestra = []
    for f in tabla["filas"][:200]:
        a, b = (celda(f, "lat"), celda(f, "lon")) if usa_geo else (celda(f, "este"), celda(f, "norte"))
        try:
            ua = geo.leer_angulo(a, "lat") if usa_geo else _num(a)
            ub = geo.leer_angulo(b, "lon") if usa_geo else _num(b)
        except geo.ErrorGeo:
            continue
        if isinstance(ua, float) and isinstance(ub, float):
            muestra.append((ua, ub))
    candidatos = geo.detectar_sistema(muestra) if muestra else []
    if s is None:
        return {"ok": False, "errores": ["Seleccione el sistema de coordenadas de los datos."],
                "candidatos": candidatos, "postes": [], "avisos": []}
    if s.tipo == "geografico" and not usa_geo:
        errores.append("El sistema elegido es geográfico pero no se asignaron Latitud y Longitud.")
    if s.tipo != "geografico" and not usa_proy:
        errores.append("El sistema elegido es proyectado/local pero no se asignaron Este y Norte.")
    gr = None
    if s.tipo == "local":
        if not georref or not georref.get("puntos"):
            errores.append("Coordenadas locales: agregue puntos de control para georreferenciar.")
        else:
            try:
                gr = geo.georreferenciar(georref["puntos"], georref.get("metodo", "helmert"))
                tol = float(georref.get("tolerancia_m", 0.10))
                if gr.rms_m > tol:
                    errores.append(f"Georreferenciación: error RMS {gr.rms_m:.3f} m supera la tolerancia "
                                   f"de {tol:.3f} m. Revise los puntos de control.")
            except geo.ErrorGeo as e:
                errores.append(str(e))
    if errores:
        return {"ok": False, "errores": errores, "candidatos": candidatos, "postes": [], "avisos": avisos,
                "georref": gr.a_dict() if gr else None}

    postes = []
    for k, f in enumerate(tabla["filas"]):
        fila_n = k + 1
        nombre = str(celda(f, "nombre")).strip()
        u, v = (celda(f, "lat"), celda(f, "lon")) if s.tipo == "geografico" else (celda(f, "este"), celda(f, "norte"))
        if not str(u).strip() and not str(v).strip():
            continue
        p = {"id": str(celda(f, "id")).strip() or nuevo_id(), "nombre": nombre or f"P{fila_n:03d}",
             "fila": fila_n, "orig": {"sistema": s.codigo, "u": str(u), "v": str(v)}, "errores": []}
        try:
            if s.tipo == "geografico":
                t = geo.transformar_punto(s.codigo, u, v)
            else:
                nu, nv = _num(u), _num(v)
                if not isinstance(nu, float) or not isinstance(nv, float):
                    raise geo.ErrorGeo("coordenada no numérica")
                t = geo.transformar_punto(s.codigo, nu, nv, gr)
            if not (geo.COLOMBIA["lat"][0] <= t["lat"] <= geo.COLOMBIA["lat"][1]
                    and geo.COLOMBIA["lon"][0] <= t["lon"] <= geo.COLOMBIA["lon"][1]):
                p["errores"].append("queda fuera de Colombia: revise el sistema o el orden de los ejes")
            p.update({"lat": round(t["lat"], 9), "lon": round(t["lon"], 9),
                      "E": round(t["E"], 4), "N": round(t["N"], 4)})
        except (geo.ErrorGeo, ValueError, OverflowError) as e:
            p["errores"].append(f"coordenadas inválidas ({e})")
        z = _num(celda(f, "z"))
        if z == "ERR":
            p["errores"].append("cota Z no numérica")
            z = None
        p["z"] = z                                   # None = sin dato (≠ 0)
        p["z_fuente"] = "archivo" if z is not None else None
        alt = _num(celda(f, "altura"))
        p["altura"] = alt if isinstance(alt, float) else None
        for k in ("poste_altura", "poste_rotura", "poste_peso"):
            v = _num(celda(f, k))
            p[k] = v if isinstance(v, float) else None
        tipo = _norm(celda(f, "tipo"))
        p["tipo"] = "R" if tipo.startswith(("r", "t", "f", "anc", "ang")) or "reten" in tipo else "S"
        p["conductor"] = str(celda(f, "conductor")).strip() or None
        p["obs"] = str(celda(f, "obs")).strip() or None
        p["bloqueado"] = False
        postes.append(p)

    # orden de los postes
    if orden == "linea_kml" and tabla.get("linea"):
        postes = _ordenar_por_linea(postes, tabla["linea"])
        avisos.append("Postes ordenados según la línea (LineString) del KML.")
    elif orden == "nombre":
        postes.sort(key=lambda p: _clave_natural(p["nombre"]))
        avisos.append("Postes ordenados por nombre (orden natural). Verifique la secuencia en el mapa.")
    else:
        avisos.append("Postes en el orden del archivo. Verifique la secuencia en el mapa antes de calcular.")

    # duplicados y vanos anómalos
    ids = {}
    for p in postes:
        if p["id"] in ids:
            p["errores"].append(f"identificador repetido con la fila {ids[p['id']]}")
        ids.setdefault(p["id"], p["fila"])
    validos = [p for p in postes if "lat" in p and not p["errores"]]
    for a, b in zip(validos[:-1], validos[1:]):
        d = geo.distancia_geodesica(a["lat"], a["lon"], b["lat"], b["lon"])
        b["vano_previo_m"] = round(d, 2)
        if d < 0.5:
            b["errores"].append(f"coincide con {a['nombre']} (a {d:.2f} m): posible duplicado")
        elif d > 600:
            avisos.append(f"Vano {a['nombre']}→{b['nombre']} de {d:.0f} m: verifique el orden o la coordenada.")
    sin_z = sum(1 for p in postes if p["z"] is None)
    if sin_z:
        avisos.append(f"{sin_z} poste(s) sin cota Z: el perfil quedará incompleto hasta agregarla "
                      "(topografía o modelo de elevación).")
    n_err = sum(1 for p in postes if p["errores"])
    return {"ok": n_err == 0, "postes": postes, "errores": [f"{n_err} fila(s) con errores; corríjalas o exclúyalas."] if n_err else [],
            "avisos": avisos, "candidatos": candidatos, "sistema": s.a_dict(),
            "georref": gr.a_dict() if gr else None, "motor_geo": geo.motor_activo()}


def _clave_natural(t):
    return [int(x) if x.isdigit() else x.lower() for x in re.split(r"(\d+)", str(t))]


def _ordenar_por_linea(postes, linea):
    acum = geo.abscisas(linea)

    def posicion(p):
        if "lat" not in p:
            return float("inf")
        mejor, pos = float("inf"), 0.0
        for (la, lo), s in zip(linea, acum):
            d = geo.distancia_geodesica(p["lat"], p["lon"], la, lo)
            if d < mejor:
                mejor, pos = d, s
        return pos
    return sorted(postes, key=posicion)

mapa_html.py:
"""
Mapa web interactivo (HTML de un solo archivo) del trazado, con fondo satelital GRATUITO.

Usa Folium (librería Python de mapas web basada en Leaflet) cuando está instalada; si no,
genera el mismo mapa con una plantilla Leaflet propia, sin dependencias. El archivo se abre
en cualquier navegador (PC o celular) y se puede enviar por correo.
Fondos: Esri World Imagery (satélite), OpenStreetMap y OpenTopoMap — sin clave, con atribución.
"""
from __future__ import annotations

import json
from html import escape

SATELITE = ("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
            "Imágenes &copy; Esri, Maxar, Earthstar Geographics y la comunidad de usuarios SIG")
CALLES = ("https://tile.openstreetmap.org/{z}/{x}/{y}.png", "&copy; colaboradores de OpenStreetMap")
TOPO = ("https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png", "&copy; OpenTopoMap (CC-BY-SA), datos &copy; OpenStreetMap")

try:  # opcional
    import folium  # type: ignore
    HAY_FOLIUM = True
except Exception:  # pragma: no cover - depende del entorno
    folium = None
    HAY_FOLIUM = False


def _postes(proyecto: dict) -> list[dict]:
    return [p for p in proyecto.get("postes", []) if p.get("lat") is not None and p.get("lon") is not None]


def _popup(p: dict) -> str:
    def v(x):
        return "sin dato" if x is None else escape(str(x))
    return (f"<b>{v(p.get('nombre'))}</b><br>Tipo: {'Retención' if p.get('tipo') == 'R' else 'Suspensión'}"
            f"<br>Cota Z: {v(p.get('z'))} m<br>Altura amarre: {v(p.get('altura'))} m"
            f"<br>Lat/Lon: {p['lat']:.6f}, {p['lon']:.6f}")


def _con_folium(nombre: str, postes: list[dict]) -> str:
    m = folium.Map(location=[postes[0]["lat"], postes[0]["lon"]], zoom_start=16, tiles=None, control_scale=True)
    folium.TileLayer(SATELITE[0], attr=SATELITE[1], name="Satélite (Esri)", max_zoom=20, max_native_zoom=19).add_to(m)
    folium.TileLayer(CALLES[0], attr=CALLES[1], name="Calles (OpenStreetMap)", max_zoom=20, max_native_zoom=19).add_to(m)
    folium.TileLayer(TOPO[0], attr=TOPO[1], name="Topográfico (OpenTopoMap)", max_zoom=20, max_native_zoom=17).add_to(m)
    if len(postes) > 1:
        folium.PolyLine([[p["lat"], p["lon"]] for p in postes], color="#e9783f", weight=4, tooltip="Trazado").add_to(m)
    for p in postes:
        folium.CircleMarker([p["lat"], p["lon"]], radius=7, color="#ffffff", weight=2, fill=True, fill_opacity=1,
                            fill_color="#c84c4c" if p.get("tipo") == "R" else "#1f6fb2",
                            tooltip=str(p.get("nombre", "")), popup=folium.Popup(_popup(p), max_width=260)).add_to(m)
    folium.LayerControl().add_to(m)
    m.fit_bounds([[min(p["lat"] for p in postes), min(p["lon"] for p in postes)],
                  [max(p["lat"] for p in postes), max(p["lon"] for p in postes)]])
    m.get_root().html.add_child(folium.Element(f"<title>{escape(nombre)}</title>"))
    return m.get_root().render()


_PLANTILLA = """<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>__TITULO__</title>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<style>html,body,#mapa{height:100%;margin:0}body{font-family:system-ui,sans-serif}
.titulo{position:absolute;z-index:1000;left:56px;top:10px;background:#17324d;color:#fff;padding:6px 12px;border-radius:8px;font-weight:600;box-shadow:0 2px 6px rgba(0,0,0,.3)}</style>
</head><body><div class="titulo">__TITULO__</div><div id="mapa"></div>
<script>
const POSTES = __POSTES__;
const F = __FONDOS__;
const m = L.map('mapa');
const capas = {};
for (const f of F) capas[f.nombre] = L.tileLayer(f.url, {maxZoom: 20, maxNativeZoom: f.max, attribution: f.attr, subdomains: 'abc'});
capas[F[0].nombre].addTo(m);
L.control.layers(capas).addTo(m);
L.control.scale({imperial: false}).addTo(m);
const ll = POSTES.map(p => [p.lat, p.lon]);
if (ll.length > 1) L.polyline(ll, {color: '#e9783f', weight: 4}).bindTooltip('Trazado').addTo(m);
for (const p of POSTES) L.circleMarker([p.lat, p.lon], {radius: 7, color: '#fff', weight: 2, fillOpacity: 1,
  fillColor: p.tipo === 'R' ? '#c84c4c' : '#1f6fb2'}).bindTooltip(p.nombre).bindPopup(p.popup).addTo(m);
m.fitBounds(L.latLngBounds(ll), {padding: [40, 40], maxZoom: 18});
</script></body></html>
"""


def _plantilla(nombre: str, postes: list[dict]) -> str:
    datos = [{"lat": p["lat"], "lon": p["lon"], "tipo": p.get("tipo"), "nombre": str(p.get("nombre", "")),
              "popup": _popup(p)} for p in postes]
    fondos = [{"nombre": "Satélite (Esri)", "url": SATELITE[0], "attr": SATELITE[1], "max": 19},
              {"nombre": "Calles (OpenStreetMap)", "url": CALLES[0], "attr": CALLES[1], "max": 19},
              {"nombre": "Topográfico (OpenTopoMap)", "url": TOPO[0], "attr": TOPO[1], "max": 17}]
    js = lambda o: json.dumps(o, ensure_ascii=False).replace("</", "<\\/")  # noqa: E731
    return (_PLANTILLA.replace("__TITULO__", escape(nombre))
            .replace("__POSTES__", js(datos)).replace("__FONDOS__", js(fondos)))


def proyecto_a_html(proyecto: dict, usar_folium: bool | None = None) -> str:
    """proyecto = {"nombre", "postes": [{nombre, lat, lon, z, altura, tipo}]} -> HTML."""
    postes = _postes(proyecto)
    if not postes:
        raise ValueError("Los postes no tienen coordenadas geográficas.")
    nombre = proyecto.get("nombre") or "Proyecto"
    if (HAY_FOLIUM if usar_folium is None else usar_folium):
        return _con_folium(nombre, postes)
    return _plantilla(nombre, postes)

motor.py:
"""
Fachada JSON del motor de cálculo.

La MISMA función se usa en:
  * el servidor Python (servidor/server.py)        -> PC y celulares en la red local
  * Python dentro del navegador (Pyodide)           -> web y celular sin servidor
  * pruebas automáticas

Entradas y salidas son dicts serializables a JSON (y bytes para archivos).

payload = {
    "proyecto": {...parámetros (ver config.Proyecto)...},
    "apoyos":  [{"nombre","x","y","altura","tipo","vano","flecha"}, ...],
    "terreno": [{"x","cota"}, ...]            # opcional
}
"""
from __future__ import annotations

import io
import json
import math
import os
import tempfile
from dataclasses import asdict
from pathlib import Path

import numpy as np
import pandas as pd

from . import __version__
from .cambio_estado import ErrorCalculo
from .config import BIBLIOTECA_CONDUCTORES, Conductor, Proyecto
from .estructuras import CABLES_TEMPLETE, CATALOGO_POSTES
from .datos import construir_datos, leer_datos
from .plantillado import calcular_plantillado, tabla_secciones


# ---------------------------------------------------------------- utilidades
def _limpio(v):
    """Convierte valores numpy/NaN a tipos JSON."""
    if isinstance(v, (np.floating, float)):
        f = float(v)
        return None if (math.isnan(f) or math.isinf(f)) else round(f, 6)
    if isinstance(v, np.integer):
        return int(v)
    if isinstance(v, np.bool_):
        return bool(v)
    return v


def _registros(df: pd.DataFrame) -> dict:
    return {"columnas": [str(c) for c in df.columns],
            "filas": [[_limpio(v) for v in fila] for fila in df.itertuples(index=False)]}


def preparar_apoyos(apoyos: list[dict]) -> tuple[list[dict], list[str], list[float | None]]:
    """Si los postes tienen latitud/longitud, calcula la abscisa geodésica (x) y usa la cota z como y.

    Devuelve (apoyos_para_calculo, errores, deflexiones_en_grados).
    """
    from . import geo
    apoyos = [dict(a) for a in (apoyos or [])]
    con_geo = [a for a in apoyos if a.get("lat") not in (None, "") and a.get("lon") not in (None, "")]
    if not apoyos or len(con_geo) != len(apoyos):
        return apoyos, [], [None] * len(apoyos)
    errores = []
    pts = [(float(a["lat"]), float(a["lon"])) for a in apoyos]
    xs = geo.abscisas(pts)
    for a, x in zip(apoyos, xs):
        a["x"] = round(x, 4)
        if a.get("z") not in (None, ""):
            a["y"] = a["z"]
        elif a.get("y") in (None, ""):
            errores.append(f"Poste {a.get('nombre') or a.get('id')}: sin cota Z. Agregue la cota "
                           "(topografía o modelo de elevación) para calcular el perfil.")
    defl = [None] * len(apoyos)
    for i in range(1, len(pts) - 1):
        az1 = geo.azimut(*pts[i - 1], *pts[i])
        az2 = geo.azimut(*pts[i], *pts[i + 1])
        defl[i] = round(geo.deflexion(az1, az2), 3)
    return apoyos, errores, defl


def _elevacion_web(fuente: str, puntos: list[dict]) -> dict:
    """Consulta la elevación desde el servidor (evita el bloqueo CORS del navegador).

    srtm: OpenTopoData SRTM 30 m (máx. 100 puntos por consulta, 1 consulta/s).
    openmeteo: Open-Meteo, Copernicus DEM 90 m.
    """
    import ssl
    import urllib.parse
    import urllib.request
    if len(puntos) > 100:
        raise ValueError("Máximo 100 puntos por consulta.")
    try:  # red corporativa con inspección SSL: usar los certificados de Windows
        import truststore  # type: ignore
        ctx = truststore.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    except Exception:
        ctx = ssl.create_default_context()
    if fuente == "srtm":
        loc = "|".join(f"{float(p['lat']):.7f},{float(p['lon']):.7f}" for p in puntos)
        url = "https://api.opentopodata.org/v1/srtm30m?interpolation=bilinear&locations=" + urllib.parse.quote(loc, safe=",|.-")
    elif fuente == "openmeteo":
        url = ("https://api.open-meteo.com/v1/elevation?latitude=" + ",".join(f"{float(p['lat']):.6f}" for p in puntos)
               + "&longitude=" + ",".join(f"{float(p['lon']):.6f}" for p in puntos))
    else:
        raise ValueError(f"Fuente desconocida: {fuente}")
    req = urllib.request.Request(url, headers={"User-Agent": "calculos-mecanicos-mt"})
    with urllib.request.urlopen(req, timeout=40, context=ctx) as r:
        j = json.loads(r.read())
    if fuente == "srtm":
        if j.get("status") != "OK":
            raise ValueError(j.get("error") or "OpenTopoData no devolvió datos")
        cotas = [x.get("elevation") for x in j["results"]]
    else:
        cotas = j.get("elevation")
        if not isinstance(cotas, list):
            raise ValueError(j.get("reason") or "Open-Meteo no devolvió datos")
    return {"cotas": cotas, "fuente": fuente}


def _terreno_por_estructuras(terreno, apoyos):
    """El perfil del terreno pasa exactamente por la base de cada estructura (su cota Z):
    el poste queda parado sobre el terreno aunque la cota se haya corregido después."""
    from .estructuras import _f
    if not terreno or not any(a.get("lat") not in (None, "") for a in apoyos):
        return terreno
    bases = [(_f(a.get("x")), _f(a.get("y"))) for a in apoyos]
    bases = [(x, y) for x, y in bases if x is not None and y is not None]
    if not bases:
        return terreno
    pts = [t for t in terreno if _f(t.get("x")) is not None and _f(t.get("cota")) is not None
           and all(abs(_f(t["x"]) - x) > 0.5 for x, _ in bases)]
    pts += [{"x": x, "cota": y} for x, y in bases]
    return sorted(pts, key=lambda t: _f(t["x"]))


_CAMPOS_ESTRUCTURA = ("poste_altura", "poste_rotura", "poste_peso", "templetes", "estructura", "bajo_cima_m")


def _datos_payload(payload: dict, proyecto: Proyecto):
    from .estructuras import _f, altura_amarre_desde_poste
    apoyos, errores, defl = preparar_apoyos(payload.get("apoyos") or [])
    # altura de amarre a partir del poste cuando no se escribió
    for a in apoyos:
        L = _f(a.get("poste_altura"))
        if L:  # la altura de amarre depende de la altura del poste (y de la estructura EH, si tiene)
            a["altura"] = round(altura_amarre_desde_poste(L, proyecto.criterios, _f(a.get("bajo_cima_m"))), 3)
    terreno = _terreno_por_estructuras(payload.get("terreno"), apoyos)
    d = construir_datos(apoyos, terreno, None, proyecto.criterios, payload.get("origen", "web"))
    d.errores = errores + d.errores
    d.deflexiones = defl
    validos = [a for a in apoyos if not (a.get("x") in (None, "") and a.get("y") in (None, "") and a.get("nombre") in (None, ""))]
    if len(validos) == len(d.apoyos):
        d.estructuras = [{k: a.get(k) for k in _CAMPOS_ESTRUCTURA} for a in validos]
    d.geo = [(a.get("lat"), a.get("lon")) for a in apoyos] if any(a.get("lat") is not None for a in apoyos) else None
    return d


# ---------------------------------------------------------------- API
def info() -> dict:
    return {
        "version": __version__,
        "proyecto_defecto": Proyecto().a_dict(),
        "conductores": {k: asdict(c) for k, c in BIBLIOTECA_CONDUCTORES.items()},
        "postes": CATALOGO_POSTES,
        "cables_templete": CABLES_TEMPLETE,
    }


def importar_excel(contenido: bytes) -> dict:
    """Lee un Excel (bytes) y devuelve las tablas editables + avisos."""
    d = leer_datos(bytes(contenido))
    if d.errores and d.apoyos.empty:
        return {"ok": False, "errores": d.errores, "advertencias": d.advertencias}
    apoyos = []
    ap = d.apoyos
    for i in range(len(ap)):
        fila = {"nombre": ap.nombre[i], "x": _limpio(ap.x[i]), "y": _limpio(ap.y[i]),
                "altura": _limpio(ap.altura[i]) if d.y_es_terreno else None,
                "tipo": "R" if ap.retencion[i] else "S"}
        if i > 0 and d.flechas_excel:
            fila["flecha"] = _limpio(d.flechas_excel[i - 1])
        apoyos.append(fila)
    # el primer/último apoyo se marcan R por regla; si el archivo no traía Tipo se dejan así
    terreno = ([] if d.terreno is None else
               [{"x": _limpio(x), "cota": _limpio(c)} for x, c in zip(d.terreno.x, d.terreno.cota)])
    return {"ok": not d.errores, "apoyos": apoyos, "terreno": terreno,
            "conductor": asdict(d.conductor) if d.conductor else None,
            "errores": d.errores, "advertencias": d.advertencias}


def _advertir_geometria(datos, res) -> None:
    """Estructuras que parecen mal ubicadas: la línea va hasta ella y regresa (rodeo grande),
    típico de un arrastre accidental en el mapa o de una coordenada mal digitada."""
    from . import geo
    pts = getattr(datos, "geo", None)
    if not pts or len(pts) < 3 or any(p[0] in (None, "") for p in pts):
        return
    nombres = list(datos.apoyos["nombre"])
    for i in range(1, len(pts) - 1):
        (la0, lo0), (la1, lo1), (la2, lo2) = [(float(a), float(b)) for a, b in pts[i - 1:i + 2]]
        a = geo.distancia_geodesica(la0, lo0, la1, lo1)
        b = geo.distancia_geodesica(la1, lo1, la2, lo2)
        c = geo.distancia_geodesica(la0, lo0, la2, lo2)
        if a + b > 2.5 * max(c, 1.0) and a + b - c > 200:
            res.advertencias.insert(0, (
                f"Estructura {nombres[i]}: parece mal ubicada. Está a {a:.0f} m y {b:.0f} m de sus vecinas, "
                f"que están a solo {c:.0f} m entre sí (la línea va y regresa). Revise sus coordenadas: "
                "pudo moverse sin querer en el mapa (en la tabla, ↺ la devuelve a su posición original)."))


def _resolver(payload: dict):
    proyecto = Proyecto.desde_dict(payload.get("proyecto"))
    datos = _datos_payload(payload, proyecto)
    res = calcular_plantillado(datos, proyecto)
    _advertir_geometria(datos, res)
    return proyecto, datos, res


def calcular(payload: dict) -> dict:
    try:
        proyecto, datos, res = _resolver(payload)
    except ErrorCalculo as e:
        return {"ok": False, "errores": str(e).split("\n- ") if "\n- " in str(e) else [str(e)]}
    except (TypeError, ValueError, KeyError) as e:
        return {"ok": False, "errores": [f"Parámetros inválidos: {e}"]}

    n = 48  # puntos por vano para graficar (suficiente y liviano para celular)
    vanos_geo = []
    for i, (c, cf) in enumerate(zip(res.catenarias, res.catenarias_frias)):
        x, y = c.muestrear(n)
        _, yf = cf.muestrear(n)
        fila = res.vanos.iloc[i]
        vanos_geo.append({
            "x": [round(float(v), 3) for v in x], "y": [round(float(v), 3) for v in y],
            "yf": [round(float(v), 3) for v in yf],
            "a": round(c.vano, 2), "f": round(c.flecha, 3),
            "xf": round(c.x_flecha_maxima, 2), "yfm": round(float(c.y(c.x_flecha_maxima)), 3),
            "cumple": fila.get("Cumple distancia", None),
            "xmin": _limpio(fila.get("X dist. mín.", None)),
            "dmin": _limpio(fila.get("Dist. mín. terreno (m)", None)),
        })
    ap = res.apoyos
    defl = getattr(datos, "deflexiones", None)
    if defl and any(v is not None for v in defl) and len(defl) == len(ap):
        ap.insert(ap.columns.get_loc("Tipo") + 1, "Deflexión (°)", defl)
    apoyos_geo = [{"nombre": r["Apoyo"], "x": _limpio(r["X (m)"]), "ya": _limpio(r["Cota amarre (m)"]),
                   "yt": _limpio(r["Cota Y (m)"]), "tipo": r["Tipo"],
                   "arranc": r["Arrancamiento"] == "SÍ", "abscisa": _limpio(r["Abscisa (m)"])}
                  for _, r in ap.iterrows()]
    if getattr(datos, "geo", None):
        for g, (la, lo) in zip(apoyos_geo, datos.geo):
            g["lat"], g["lon"] = la, lo
    terreno = None
    if datos.terreno is not None:
        terreno = {"x": [_limpio(v) for v in datos.terreno.x], "y": [_limpio(v) for v in datos.terreno.cota]}
    elif datos.y_es_terreno:
        terreno = {"x": [_limpio(v) for v in datos.apoyos.x], "y": [_limpio(v) for v in datos.apoyos.y]}

    circuitos = []
    for c in res.circuitos:
        vs = []
        for k, (cc, cf) in enumerate(zip(c.res.catenarias, c.res.catenarias_frias)):
            x, y = cc.muestrear(n)
            _, yf = cf.muestrear(n)
            fila = c.res.vanos.iloc[k]
            vs.append({"i": c.i0 + k, "x": [round(float(v), 3) for v in x], "y": [round(float(v), 3) for v in y],
                       "yf": [round(float(v), 3) for v in yf], "a": round(cc.vano, 2), "f": round(cc.flecha, 3),
                       "cumple": fila.get("Cumple distancia", None),
                       "xmin": _limpio(fila.get("X dist. mín.", None)), "dmin": _limpio(fila.get("Dist. mín. terreno (m)", None))})
        ya = list(c.res.apoyos["Cota amarre (m)"])
        circuitos.append({"nombre": c.nombre, "tension_kv": _limpio(c.circuito.tension_kv),
                          "conductor": c.circuito.conductor.nombre, "i0": c.i0, "i1": c.i1,
                          "vanos": vs, "ya": [_limpio(v) for v in ya], "vanos_tabla": _registros(c.res.vanos)})
    extra = {}
    if res.tabla_circuitos is not None:
        extra["circuitos"] = _registros(res.tabla_circuitos)
    if res.separaciones is not None:
        extra["separaciones"] = _registros(res.separaciones)
    if res.cargas_circuitos is not None:
        extra["cargas_circuitos"] = _registros(res.cargas_circuitos)
    return {
        "ok": True,
        **extra,
        "resumen": {k: _limpio(v) for k, v in res.resumen.items()},
        "vanos": _registros(res.vanos),
        "apoyos": _registros(res.apoyos),
        "secciones": _registros(tabla_secciones(res)),
        "postes": _registros(res.postes) if res.postes is not None else None,
        "advertencias": res.advertencias,
        "perfil": {"vanos": vanos_geo, "apoyos": apoyos_geo, "terreno": terreno,
                   "dmin": proyecto.criterios.distancia_minima_terreno_m,
                   "y_es_terreno": datos.y_es_terreno, "modo": proyecto.modo_flecha,
                   "vanos_por_pagina": proyecto.salida.vanos_por_pagina,
                   "circuito_principal": proyecto.criterios.nombre_circuito_principal or "Circuito 1",
                   "circuitos": circuitos},
    }


_FORMATOS = {
    "xlsx": ("_RESULTADOS.xlsx", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"),
    "pdf": ("_PERFIL.pdf", "application/pdf"),
    "dxf": ("_PERFIL.dxf", "application/dxf"),
}


def _base(nombre: str) -> str:
    return "".join(ch if ch.isalnum() or ch in "-_" else "_" for ch in nombre)[:60] or "PROYECTO"


def exportar(payload: dict, formato: str) -> tuple[bytes, str, str]:
    """Devuelve (contenido, nombre_archivo, tipo_mime)."""
    if formato in ("kml", "kmz", "html"):
        from . import kml
        nombre = (payload.get("proyecto") or {}).get("nombre") or "Proyecto"
        doc = {"nombre": nombre, "postes": payload.get("apoyos") or []}
        if not any(p.get("lat") is not None for p in doc["postes"]):
            raise ValueError("Los postes no tienen coordenadas geográficas: importe o ubique los postes en el mapa.")
        if formato == "html":
            from .mapa_html import proyecto_a_html
            return proyecto_a_html(doc).encode("utf-8"), _base(nombre) + "_MAPA.html", "text/html; charset=utf-8"
        if formato == "kml":
            return kml.proyecto_a_kml(doc).encode("utf-8"), _base(nombre) + ".kml", "application/vnd.google-earth.kml+xml"
        return kml.proyecto_a_kmz(doc), _base(nombre) + ".kmz", "application/vnd.google-earth.kmz"
    from .exportar import exportar_dxf, exportar_excel, exportar_pdf
    if formato not in _FORMATOS:
        raise ValueError(f"Formato no soportado: {formato}")
    proyecto, _, res = _resolver(payload)
    sufijo, mime = _FORMATOS[formato]
    base = _base(proyecto.nombre)
    fn = {"xlsx": exportar_excel, "pdf": exportar_pdf, "dxf": exportar_dxf}[formato]
    with tempfile.TemporaryDirectory() as tmp:
        ruta = Path(tmp) / f"salida{sufijo}"
        fn(res, ruta)
        return ruta.read_bytes(), base + sufijo, mime


def plantilla_excel() -> bytes:
    """Plantilla de datos vacía con las columnas reconocidas."""
    buf = io.BytesIO()
    ej = pd.DataFrame({
        "Apoyo": ["AP-001", "AP-002", "AP-003"],
        "Coordenada en X": [0, 120, 250],
        "Coordenada en Y": [1000.0, 1002.5, 998.0],
        "Altura amarre (m)": [9.6, 10.0, 9.6],
        "Tipo": ["R", "S", "R"],
    })
    ter = pd.DataFrame({"Abscisa": [0, 60, 120, 185, 250], "Cota": [1000, 1001.2, 1002.5, 999.0, 998.0]})
    ayuda = pd.DataFrame({"Instrucciones": [
        "Hoja 'Datos': un apoyo por fila, abscisas X crecientes (m).",
        "Coordenada en Y: cota del terreno si existe 'Altura amarre'; si no, cota del punto de amarre.",
        "Tipo: R = retención (inicia/termina sección de tendido), S = suspensión.",
        "Hoja 'Terreno' (opcional): perfil topográfico para verificar distancias de seguridad.",
        "Columna opcional 'Flecha' (m): solo para el modo 'excel'.",
    ]})
    with pd.ExcelWriter(buf, engine="openpyxl") as xw:
        ej.to_excel(xw, sheet_name="Datos", index=False)
        ter.to_excel(xw, sheet_name="Terreno", index=False)
        ayuda.to_excel(xw, sheet_name="Ayuda", index=False)
    return buf.getvalue()


